import{_ as t,o,c as s,a2 as a}from"./chunks/framework.BEUshCVJ.js";const p=JSON.parse('{"title":"Release process","description":"","frontmatter":{},"headers":[],"relativePath":"contribute/release.md","filePath":"contribute/release.md","lastUpdated":1793232148000}'),r={name:"contribute/release.md"};function n(i,e,h,d,c,l){return o(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="release-process" tabindex="-1">Release process <a class="header-anchor" href="#release-process" aria-label="Permalink to &quot;Release process&quot;">​</a></h1><p>Releases are automatic. Every push to the default branch that changes the app is released once CI passes on it; nobody bumps the version or pushes a tag by hand.</p><h2 id="before-merging" tabindex="-1">Before merging <a class="header-anchor" href="#before-merging" aria-label="Permalink to &quot;Before merging&quot;">​</a></h2><ol><li>Add the change to the <strong>Unreleased</strong> section of both <a href="/meetcue/reference/changelog">changelogs</a>. The release moves these entries under the new version and uses them as the release notes.</li><li>Check prices in <code>crates/core/data/pricing.json</code> against the providers&#39; pricing pages and update the <code>verified</code> dates and <code>updated</code> when they change. The app downloads this file from the documentation site, so a price fix only needs a push to the default branch, not a release.</li><li>For changes to audio, recognition or windows, run the <a href="/meetcue/test-checklist">hardware test checklist</a> on Windows and macOS with builds from the branch (CI uploads <code>MeetCue-windows-x64</code> for every push).</li></ol><h2 id="choosing-the-version" tabindex="-1">Choosing the version <a class="header-anchor" href="#choosing-the-version" aria-label="Permalink to &quot;Choosing the version&quot;">​</a></h2><p>The version is the latest <code>v*</code> tag with its patch number raised. Put a marker in the pull request title, or in the title of a commit pushed straight to the default branch, to change that. A marker that only appears in a description is ignored, so describing the markers never triggers them.</p><table tabindex="0"><thead><tr><th>Marker</th><th>Effect</th></tr></thead><tbody><tr><td><code>[release minor]</code></td><td>0.1.5 → 0.2.0</td></tr><tr><td><code>[release major]</code></td><td>0.1.5 → 1.0.0</td></tr><tr><td><code>[skip release]</code></td><td>in the newest commit: don&#39;t release this push</td></tr></tbody></table><p>Pushes that only touch documentation, workflows or the Scoop manifest are not released. To release by hand, run the <strong>Release</strong> workflow from the Actions tab and choose which part to raise.</p><h2 id="what-the-release-workflow-does" tabindex="-1">What the release workflow does <a class="header-anchor" href="#what-the-release-workflow-does" aria-label="Permalink to &quot;What the release workflow does&quot;">​</a></h2><p><code>.github/workflows/release.yml</code> runs when CI finishes on the default branch:</p><ol><li>Decides the version. Only the newest commit is released: if the branch moved on while CI ran, the newer commit&#39;s run releases both.</li><li>Builds <code>MeetCue.exe</code> on Windows with that version written into the manifests, checks <code>MeetCue.exe --version</code>, and packs <code>MeetCue.exe</code>, <code>LICENSE</code> and the README files into <code>meetcue-win-x64.zip</code>.</li><li>Runs <code>scripts/set-version.mjs</code>, which writes the version into <code>Cargo.toml</code>, <code>Cargo.lock</code>, the <code>package.json</code> files and <code>package-lock.json</code>, moves the <strong>Unreleased</strong> changelog entries under the new version, and points <code>bucket/meetcue.json</code> at the new zip and its SHA-256 hash.</li><li>Commits this as &quot;Release x.y.z&quot; to the default branch, as the identity in the repository variables <code>GIT_NAME</code> and <code>GIT_EMAIL</code>, and tags it <code>vx.y.z</code>. The commit and tag are pushed together; if the branch moved in the meantime, nothing is published and the next run releases instead.</li><li>Creates the GitHub release with the zip and the changelog section as notes, and republishes the documentation site.</li><li>Installs Scoop on a Windows runner, installs MeetCue from the tagged manifest and checks that it prints the new version.</li></ol><p><code>npm run check:versions</code> checks that every manifest, both lockfiles and the Scoop manifest carry the same version, so the committed version always equals the latest release. The hash is only ever computed and committed by the workflow, in the same run that uploads the zip. Never replace a release asset by hand; publish a new version instead.</p><p>If a run fails after the commit and tag were pushed, use <strong>Re-run failed jobs</strong>: it finishes the release for the same tag.</p><h2 id="after-the-release" tabindex="-1">After the release <a class="header-anchor" href="#after-the-release" aria-label="Permalink to &quot;After the release&quot;">​</a></h2><ol><li>Check that <code>scoop update meetcue</code> picks up the new version on Windows and macOS.</li><li>Check that the documentation site shows the new changelog.</li></ol><h2 id="repository-settings" tabindex="-1">Repository settings <a class="header-anchor" href="#repository-settings" aria-label="Permalink to &quot;Repository settings&quot;">​</a></h2><p>These are set once:</p><ul><li><strong>Settings › Pages</strong>: source is the <code>gh-pages</code> branch. The docs workflow publishes there on every change to <code>docs/</code> or <code>errors.json</code> on the default branch.</li><li><strong>Settings › Secrets and variables › Actions › Variables</strong>: <code>GIT_NAME</code> and <code>GIT_EMAIL</code> for commits made by workflows.</li><li><strong>Settings › Actions › General › Workflow permissions</strong>: the workflow pushes to the default branch with <code>GITHUB_TOKEN</code>, so a branch protection rule on it must let GitHub Actions push.</li><li>The repository must be public, or Scoop can&#39;t download release assets.</li></ul><p>Mac releases are built on Apple Silicon and Intel runners as <code>.app</code> ZIPs and DMGs. The bundle check verifies privacy descriptions, the macOS 13 minimum, signature integrity and <code>--version</code>. Packages currently use ad-hoc signing; Developer ID signing and notarization require Apple credentials and are not configured by this change.</p>',19)])])}const m=t(r,[["render",n]]);export{p as __pageData,m as default};
